// --- ietf.Iphdr..Init
// Set all fields to initial values.
void ietf::Iphdr_Init(ietf::Iphdr& parent) {
    parent.version_ihl = u8(0);
    parent.tos = u8(0);
    parent.tot_len_be = htobe16(0); // write big-endian value to memory
    parent.id_be = htobe16(0); // write big-endian value to memory
    parent.frag_off_be = htobe16(0); // write big-endian value to memory
    parent.ttl = u8(0);
    parent.protocol = u8(0);
    parent.check_be = htobe16(0); // write big-endian value to memory
    parent.saddr_be = htobe32(0); // write big-endian value to memory
    parent.daddr_be = htobe32(0); // write big-endian value to memory
}

