// --- ietf.Tcphdr..Init
// Set all fields to initial values.
void ietf::Tcphdr_Init(ietf::Tcphdr& parent) {
    parent.source_be = htobe16(0); // write big-endian value to memory
    parent.dest_be = htobe16(0); // write big-endian value to memory
    parent.seq_be = htobe32(0); // write big-endian value to memory
    parent.ack_seq_be = htobe32(0); // write big-endian value to memory
    parent.doff_flags_be = htobe16(0); // write big-endian value to memory
    parent.window_be = htobe16(0); // write big-endian value to memory
    parent.check_be = htobe16(0); // write big-endian value to memory
    parent.urg_ptr_be = htobe16(0); // write big-endian value to memory
}

