    algo_assert(sizeof(((ietf::Iphdr*)0)->version_ihl)*8 >= 8);
    // check that bitfield fits width
    algo_assert(sizeof(((ietf::Iphdr*)0)->tos)*8 >= 8);
    // check that bitfield fits width
    algo_assert(sizeof(((ietf::Iphdr*)0)->frag_off_be)*8 >= 16);
    algo_assert(_offset_of(ietf::Iphdr, daddr_be) + sizeof(((ietf::Iphdr*)0)->daddr_be) == sizeof(ietf::Iphdr));
    algo_assert(_offset_of(ietf::Ipv4, ipv4) + sizeof(((ietf::Ipv4*)0)->ipv4) == sizeof(ietf::Ipv4));
    algo_assert(_offset_of(ietf::Ipport, port) + sizeof(((ietf::Ipport*)0)->port) == sizeof(ietf::Ipport));
    algo_assert(_offset_of(ietf::Ipv4Addr, addr_be) + sizeof(((ietf::Ipv4Addr*)0)->addr_be) == sizeof(ietf::Ipv4Addr));
    // check that bitfield fits width
    algo_assert(sizeof(((ietf::Tcphdr*)0)->doff_flags_be)*8 >= 16);
    algo_assert(_offset_of(ietf::Tcphdr, urg_ptr_be) + sizeof(((ietf::Tcphdr*)0)->urg_ptr_be) == sizeof(ietf::Tcphdr));
    algo_assert(_offset_of(ietf::Udphdr, check_be) + sizeof(((ietf::Udphdr*)0)->check_be) == sizeof(ietf::Udphdr));
    // check that bitfield fits width
    algo_assert(sizeof(((ietf::Vlanhdr*)0)->tci_be)*8 >= 16);
    algo_assert(_offset_of(ietf::Vlanhdr, ethertype_be) + sizeof(((ietf::Vlanhdr*)0)->ethertype_be) == sizeof(ietf::Vlanhdr));
